schema.example:
"{
  "name": "Monthly Sales by Product (Updated)",
  "description": "Updated description for monthly sales report",
  "definition": {
    "base_entity": "sales_orders",
    "domain": "sales",
    "version": 1,
    "columns": [
      {
        "id": "sales_orders.order_date",
        "kind": "dimension",
        "entity": "sales_orders",
        "field": "order_date",
        "label": "Order Month",
        "granularity": "month"
      },
      {
        "id": "products.sku",
        "kind": "dimension",
        "entity": "products",
        "field": "sku",
        "label": "SKU"
      },
      {
        "id": "products.name",
        "kind": "dimension",
        "entity": "products",
        "field": "name",
        "label": "Product Name"
      },
      {
        "id": "sales_orders.total",
        "kind": "measure",
        "entity": "sales_orders",
        "field": "total",
        "label": "Total Sales",
        "aggregation": "sum"
      },
      {
        "id": "sales_orders.id",
        "kind": "measure",
        "entity": "sales_orders",
        "field": "id",
        "label": "Order Count",
        "aggregation": "count"
      }
    ],
    "filters": {
      "conjunction": "and",
      "children": [
        {
          "type": "condition",
          "condition": {
            "column": "sales_orders.status",
            "operator": "!=",
            "value": "cancelled"
          }
        }
      ]
    },
    "sorts": [
      {
        "column_id": "sales_orders.order_date",
        "direction": "desc"
      }
    ],
    "limit": 1000
  },
  "visibility": "shared"
}"
